def credential_exclusion_hits(text: str, source: str = "") -> list[dict[str, Any]]:
    hits: list[dict[str, Any]] = []
    seen: set[tuple[str, int, int]] = set()
    for category, pattern in CREDENTIAL_PATTERNS:
