  color: #d9d4ca;
  font-size: 11px;
  line-height: 1.45;
}

.proposal-approval-band input,
.proposal-manual-rollback input {
  flex: 0 0 auto;
  margin-top: 2px;
  accent-color: #7ee8d4;
}

.proposal-approval-band button,
.proposal-manual-rollback button {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 34px;
  border: 1px solid rgba(126, 232, 212, 0.4);
  border-radius: 7px;
  background: rgba(126, 232, 212, 0.12);
  color: #e8fffb;
  padding: 6px 11px;
  font-size: 11px;
  font-weight: 700;
}

.proposal-manual-rollback button {
  border-color: rgba(245, 199, 107, 0.42);
  background: rgba(245, 199, 107, 0.1);
  color: #ffe8b8;
}

.proposal-approval-band button:disabled,
.proposal-manual-rollback button:disabled,
.proposal-workspace-close:disabled,
.proposal-review-list-item:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.proposal-action-error,
.proposal-action-result {
  margin: 14px 0 0;
  border-left: 3px solid #f08f8f;
  background: rgba(240, 143, 143, 0.08);
  color: #ffd0d0;
  padding: 10px 12px;
  font-size: 11px;
  line-height: 1.5;
}

.proposal-action-result {
  border-left-color: #7ee8d4;
  color: #d9d4ca;
}

.proposal-action-result-rollback_or_needs_revision {
  border-left-color: #f5c76b;
}

.proposal-action-result strong {
  color: #f4f1e8;
}

.proposal-action-result p {
  margin: 5px 0 0;
}

.visual-focus-workspace:not(.home-workspace) .command-palette {
  display: none;
}

.content-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 320px);
  min-height: 0;
  overflow: hidden;

  .proposal-diff-narrator,
  .proposal-scope-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .proposal-diff-narrator section,
  .proposal-diff-narrator section:nth-child(even),
  .proposal-diff-narrator section:last-child {
    grid-column: auto;
    border-left: 0;
    padding: 9px 0;
  }

  .proposal-approval-band,
  .proposal-manual-rollback {
    align-items: stretch;
    flex-direction: column;
  }

  .proposal-approval-band button,
  .proposal-manual-rollback button {
    width: 100%;
  }
}

