 ["r4_e2e_body","sed -n '280,620p' OpenAIDatabase/apps/memory-atlas/scripts/validate_memory_atlas_v1_2_proposal_e2e.cjs"]
];
const out=await Promise.all(cmds.map(async([n,c])=>[n,await tools.exec_command({cmd:c,workdir:wd,yield_time_ms:10000,max_output_tokens:14000})]));
