.controls {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) minmax(190px, 260px) repeat(3, minmax(130px, 200px));
  gap: 10px;
}

.interaction-lens {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) auto auto minmax(128px, 0.4fr) minmax(220px, 0.9fr);
  align-items: center;
  gap: 8px;
  min-height: 42px;
  border: 1px solid rgba(244, 241, 232, 0.1);
  border-radius: 8px;
  background: rgba(9, 10, 13, 0.38);
  padding: 7px 9px;
}

.lens-focus {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  min-width: 0;
}

.lens-focus div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.lens-focus strong,
.lens-focus span,
.filter-chip-row strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lens-focus strong {
  color: #f4f1e8;
  font-size: 13px;
}

.lens-focus span {
  color: #a8a196;
  font-size: 11px;
}

.lens-badge {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  border: 1px solid rgba(126, 224, 248, 0.26);
  border-radius: 999px;
  background: rgba(126, 224, 248, 0.08);
  color: #dff7ff;
  padding: 0 8px;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.lens-stepper,
.lens-actions,
.lens-state-strip,
.filter-chip-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.lens-stepper {
  justify-content: center;
}

.lens-stepper span {
  min-width: 46px;
  color: #a8a196;
  font-size: 11px;
  text-align: center;
}

.lens-stepper button,
.lens-actions button,
.filter-chip-row button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 30px;
  border: 1px solid rgba(244, 241, 232, 0.12);
  border-radius: 8px;
  background: rgba(244, 241, 232, 0.05);
  color: #d9d4ca;
  padding: 0 8px;
}

.lens-stepper button {
  width: 30px;
  padding: 0;
}

.lens-actions button {
  white-space: nowrap;
}

.lens-state-strip {
  min-width: 0;
  overflow: hidden;
  border-left: 1px solid rgba(244, 241, 232, 0.12);
  padding-left: 8px;
}

.lens-state-strip span,
.lens-state-strip em {
  color: #8f8a82;
  font-size: 10px;
  font-style: normal;
  white-space: nowrap;
}

.lens-state-strip strong {
  min-width: 0;
  overflow: hidden;
  color: #dff7ff;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lens-stepper button:not(:disabled):hover,
.lens-stepper button:not(:disabled):focus-visible,
.lens-actions button:not(:disabled):hover,
.lens-actions button:not(:disabled):focus-visible,
.filter-chip-row button:hover,
.filter-chip-row button:focus-visible {
  border-color: rgba(126, 232, 212, 0.65);
  background: rgba(126, 232, 212, 0.12);
  color: #ffffff;
  outline: none;
}

.lens-stepper button:disabled,
.lens-actions button:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.filter-chip-row {
  justify-content: end;
  overflow-x: auto;
  scrollbar-width: none;
}

.filter-chip-row::-webkit-scrollbar {
  display: none;
}

.filter-chip-row button {
  flex: 0 0 auto;
  max-width: 180px;
  border-color: rgba(126, 224, 248, 0.18);
}

.filter-chip-row .timeline-range-chip,
.timeline-sync-pill {
  border-color: rgba(126, 232, 212, 0.3);
  background: rgba(126, 232, 212, 0.08);
}

.timeline-sync-pill {
  display: inline-flex;
  max-width: 320px;
  overflow: hidden;
  border: 1px solid rgba(126, 232, 212, 0.3);
  border-radius: 999px;
  color: #dff7ff !important;
  padding: 4px 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.filter-chip-row button span {
  color: #8fd3ff;
  font-size: 10px;
}

.filter-chip-row button strong {
  color: #f4f1e8;
  font-size: 11px;
}

.filter-chip-row button em {
  color: #a8a196;
  font-style: normal;
}

.filter-empty {
  color: #8f8a82;
  font-size: 11px;
  white-space: nowrap;
}

.search-box,
.select-filter {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  border: 1px solid rgba(244, 241, 232, 0.14);
  border-radius: 8px;
  background: rgba(16, 16, 20, 0.72);
  padding: 0 12px;
}

.search-box input,
.select-filter select {
  width: 100%;
  min-width: 0;
  border: 0;
  color: #f4f1e8;
  background: transparent;
  outline: none;
}

.select-filter span {
  flex: 0 0 auto;
  color: #b6b1a6;
  font-size: 12px;
}

.command-palette {
  display: grid;
  align-content: start;
  gap: 6px;
  min-height: 0;
  height: 100%;
  max-height: 100%;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  border: 1px solid rgba(126, 232, 212, 0.18);
  border-radius: 8px;
  background: rgba(14, 18, 24, 0.72);
  padding: 8px;
}

.command-palette-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.command-palette-heading-copy {
  display: grid;
  grid-template-columns: auto auto;
  align-items: baseline;
  min-width: 0;
  gap: 1px 7px;
}

.home-status-card.dominant {
  border-color: rgba(143, 211, 255, 0.28);
}

.home-status-card.rising,
.home-status-card.proto-star {
  border-color: rgba(126, 232, 212, 0.32);
}

.home-status-card.declining {
  border-color: rgba(199, 167, 255, 0.28);
}

.home-status-card.black-hole {
  border-color: rgba(244, 143, 177, 0.32);
}

.home-behavior-intelligence-panel {
  display: grid;
  gap: 10px;
  min-width: 0;
  border-top: 1px solid rgba(244, 241, 232, 0.08);
  border-bottom: 1px solid rgba(244, 241, 232, 0.08);
  background: rgba(9, 10, 13, 0.3);
  padding: 12px 16px;
}

.home-behavior-count-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

.home-behavior-count-row span {
  display: flex;
  min-width: 0;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  border: 1px solid rgba(244, 241, 232, 0.1);
  border-radius: 8px;
  background: rgba(244, 241, 232, 0.045);
  color: #b6b1a6;
  font-size: 11px;
  line-height: 1.2;
  padding: 8px 10px;
}

.home-behavior-count-row strong {
  color: #f4f1e8;
  font-size: 18px;
  line-height: 1;
}

.home-behavior-card-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  min-width: 0;
}

.home-behavior-card {
  display: grid;
  align-content: start;
  gap: 10px;
  min-width: 0;
  border: 1px solid rgba(143, 211, 255, 0.18);
  border-radius: 8px;
  background: rgba(143, 211, 255, 0.045);
