.bubble-axis {
  stroke: rgba(244, 241, 232, 0.22);
  stroke-width: 2;
}

.cluster-tree-root {
  fill: rgba(126, 232, 212, 0.2);
  stroke: rgba(126, 232, 212, 0.7);
}

.cluster-tree-svg text,
.bubble-map-svg text {
  fill: #d9d4ca;
  font-size: 11px;
  letter-spacing: 0;
}

.cluster-tree-branch,
.semantic-bubble {
  cursor: pointer;
  outline: none;
}

.cluster-tree-branch circle {
  fill: rgba(143, 211, 255, 0.16);
  stroke: rgba(143, 211, 255, 0.72);
  transition: fill 160ms ease, stroke 160ms ease;
}

.cluster-tree-branch:hover circle,
.cluster-tree-branch:focus-visible circle,
