  border-color: rgba(143, 211, 255, 0.72);
  background-color: rgba(143, 211, 255, 0.08);
}

.friction-heatmap-grid strong,
.latent-radar-selected strong,
.formula-explorer-list strong {
  color: #f4f1e8;
