}

.friction-heatmap-grid span,
.friction-heatmap-grid small,
.latent-radar-selected span,
.latent-radar-selected small,
.formula-explorer-list span,
.formula-explorer-list small,
.formula-explorer-list em,
.evidence-timeline-track span,
.evidence-timeline-track small {
  color: #aaa49a;
  font-size: 10px;
  line-height: 1.35;
}

.latent-radar-svg circle {
  fill: none;
  stroke: rgba(244, 241, 232, 0.16);
}

.latent-radar-svg polygon {
  fill: rgba(143, 211, 255, 0.18);
  stroke: #8fd3ff;
  stroke-width: 2;
}

.latent-radar-axis {
  cursor: pointer;
  outline: none;
}

.latent-radar-axis line {
  stroke: rgba(244, 241, 232, 0.24);
  stroke-width: 1.5;
}

.latent-radar-axis.active text,
.latent-radar-axis:hover text,
.latent-radar-axis:focus-visible text {
  fill: #f6c56f;
}

.latent-radar-selected {
  background: rgba(244, 241, 232, 0.045);
}

.latent-radar-selected span {
  color: #8fd3ff;
  font-weight: 800;
}

.evidence-timeline-track {
  position: relative;
  display: grid;
  align-content: start;
  gap: 8px;
  min-height: 220px;
  min-width: 0;
  border-radius: 8px;
  background: linear-gradient(90deg, rgba(126, 232, 212, 0.14), rgba(246, 197, 111, 0.12));
  overflow: hidden;
  padding: 12px 10px 12px 18px;
}

.evidence-timeline-track::before {
  position: absolute;
  top: 16px;
  bottom: 16px;
  left: 10px;
  width: 2px;
  background: rgba(244, 241, 232, 0.22);
  content: "";
}

.evidence-timeline-track button {
  position: relative;
  left: auto !important;
  width: 100%;
  transform: none;
  background: rgba(9, 10, 13, 0.78);
}

.evidence-timeline-track strong {
  color: #7ee8d4;
  font-size: 10px;
  line-height: 1.2;
}

.formula-explorer-list {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.formula-explorer-list button {
  background: rgba(244, 241, 232, 0.045);
}

.formula-explorer-list span {
  color: #8fd3ff;
  font-weight: 800;
}

.formula-explorer-list em {
  color: #f6c56f;
  font-style: normal;
}

.human-question-map-panel {
  display: grid;
  gap: 10px;
  min-width: 0;
  border-top: 1px solid rgba(126, 232, 212, 0.18);
