  font-style: normal;
  font-weight: 500;
  line-height: 1.35;
}

.human-question-map-entry p {
  color: #f6c56f;
  font-weight: 800;
}

.human-question-map-entry b {
  color: #aaa49a;
}

.human-question-map-exclusion-list {
