.human-question-map-exclusion-list strong {
  color: #f08fa3;
  font-size: 11px;
  line-height: 1.2;
}

.human-question-map-exclusion-list small {
  color: #d9d4ca;
  font-size: 10px;
  line-height: 1.35;
}

.home-action-panel {
  display: grid;
  gap: 10px;
  min-height: 0;
  border-top: 1px solid rgba(244, 241, 232, 0.08);
  padding: 12px 16px 10px;
