.home-section-summary-row,
.home-operation-chip-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  min-width: 0;
}

.home-section-summary-row {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.home-operation-chip {
  display: grid;
  gap: 3px;

