const r = await tools.exec_command({
  cmd: "node -e \"const p=require('./package.json'); console.log(JSON.stringify(p.scripts,null,2))\"",
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "sed -n '1,330p' scripts/build_memory_atlas_data.py && rg -n \"build_behavior_intelligence_summary|behavior_intelligence\" tests/test_build_memory_atlas_data.py tests --glob 'test*memory_atlas*data*' | head -120",
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 10000,
  max_output_tokens: 22000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "rg -n \"build_behavior_intelligence_summary|memory_atlas_behavior_intelligence_display\" tests",
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 10000,
  max_output_tokens: 8000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "cat 机器治理/参数与公式/formula_what_if_defaults.v1_2_s07_p3.json && cat data/derived/economic_proxy/formula_what_if_preview.json",
  workdir: "[REDACTED_LOCAL_PATH]",
  yield_time_ms: 10000,
  max_output_tokens: 16000
});
text(r.output);

