  return signal;
}

async function validateInitialAdaptiveOverlay(page) {
  await page.waitForFunction(() => {
    const signal = window.__memoryAtlasGalaxySignal?.();
    return Boolean(
      signal
        && signal.adaptiveQualityEnabled === true
        && signal.quality === "mid"
        && signal.fps > 0
        && signal.sampleSeconds >= 0.8,
